"""執行 47 項自動檢查：印出 PASS/FAIL、寫入 outputs/validation_table.json；
加 --markdown 時另寫 VALIDATION.md。有任何失敗時 exit code = 1。"""
import json
import os
import sys
import numpy as np
import _path  # noqa: F401
from urea_nitrate_cell.validation import run_all


def to_markdown(rows):
    fmt = lambda v: "—" if v is None else (f"{v:.4g}" if isinstance(v, (int, float)) else str(v))
    out = ["# Validation results", "",
           f"{sum(r['ok'] for r in rows)} / {len(rows)} checks passed. "
           "Generated by `python scripts/validate.py --markdown`; CI reruns every check on each push.", "",
           "| # | Category | Check | Model | Expected | Tolerance | Result | How it is checked |",
           "|---|---|---|---|---|---|---|---|"]
    for i, r in enumerate(rows, 1):
        note = f"；{r['note']}" if r["note"] else ""
        out.append(f"| {i} | {r['cat']} | {r['name']} | {fmt(r['value'])} | {fmt(r['expect'])} | {fmt(r['tol'])} | "
                   f"{'PASS' if r['ok'] else '**FAIL**'} | {r['how']}{note} |")
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    rows = run_all(verbose=True)
    n_fail = sum(not r["ok"] for r in rows)
    print(f"\n共 {len(rows)} 項，失敗 {n_fail} 項")
    os.makedirs(_path.OUTPUTS, exist_ok=True)
    json.dump(rows, open(os.path.join(_path.OUTPUTS, "validation_table.json"), "w"), ensure_ascii=False, indent=1,
              default=lambda o: float(o) if isinstance(o, (np.floating, np.integer)) else str(o))
    if "--markdown" in sys.argv:
        open(os.path.join(_path.ROOT, "VALIDATION.md"), "w").write(to_markdown(rows))
        print("wrote VALIDATION.md")
    sys.exit(1 if n_fail else 0)
